export const AREA_TYPES={aisle:{label:'通道',color:'#fff0bf',stroke:'#c7a34b'},inbound:{label:'入库暂存区',color:'#d9edf9',stroke:'#77a8c3'},outbound:{label:'出库拣货暂存区',color:'#fbe0c6',stroke:'#c69a72'}};
export function corners(r){const a=(r.rotation||0)*Math.PI/180,w=r.cols?r.cols*r.width:r.width,d=r.depth;return [[0,0],[w,0],[w,d],[0,d]].map(([x,y])=>({x:r.x+x*Math.cos(a)-y*Math.sin(a),y:r.y+x*Math.sin(a)+y*Math.cos(a)}));}
export function overlaps(a,b){const pa=corners(a),pb=corners(b);for(const p of [pa,pb])for(let i=0;i<4;i++){const q=p[(i+1)%4],axis={x:-(q.y-p[i].y),y:q.x-p[i].x};const av=pa.map(v=>v.x*axis.x+v.y*axis.y),bv=pb.map(v=>v.x*axis.x+v.y*axis.y);if(Math.max(...av)<=Math.min(...bv)+1e-8||Math.max(...bv)<=Math.min(...av)+1e-8)return false;}return true;}
export function validateArea(a,boundary=false){if(typeof a.name!=='string'||!a.name.trim())throw Error('请填写名称');if(!boundary&&!AREA_TYPES[a.type])throw Error('区域类型无效');for(const k of ['x','y','width','depth','rotation'])if(!Number.isFinite(a[k]))throw Error('请输入有效数值');if(a.width<.5||a.depth<.5||a.width>400||a.depth>400)throw Error('长宽需在 0.5–400 米之间');if(Math.abs(a.x)>200||Math.abs(a.y)>200)throw Error('坐标需在 -200 至 200 米之间');if(boundary&&a.rotation!==0)throw Error('矩形仓库边界暂不支持旋转');}
export function ensureSpatial(model){if(model.boundary&&Array.isArray(model.areas))return model;const points=model.racks.flatMap(corners),minX=Math.min(0,...points.map(p=>p.x))-2,minY=Math.min(0,...points.map(p=>p.y))-2,maxX=Math.max(33,...points.map(p=>p.x))+3,maxY=Math.max(26,...points.map(p=>p.y))+3;model.boundary={id:'boundary',name:'成品仓边界',x:minX,y:minY,width:Math.min(400,maxX-minX),depth:Math.min(400,maxY-minY+8),rotation:0};model.areas=[];return model;}
export function defaultAreas(model){const b=model.boundary,y=b.y+b.depth-7;return [{id:crypto.randomUUID(),name:'主通道',type:'aisle',x:b.x+1,y:y-3,width:b.width-2,depth:2.5,rotation:0},{id:crypto.randomUUID(),name:'入库暂存区',type:'inbound',x:b.x+2,y,width:10,depth:5,rotation:0},{id:crypto.randomUUID(),name:'出库拣货暂存区',type:'outbound',x:b.x+15,y,width:12,depth:5,rotation:0}];}
export function spatialWarnings(model){const b=model.boundary,result=[];for(const o of [...model.racks,...model.areas]){if(corners(o).some(p=>p.x<b.x-1e-8||p.y<b.y-1e-8||p.x>b.x+b.width+1e-8||p.y>b.y+b.depth+1e-8))result.push({id:o.id,text:`${o.name} 超出仓库边界`});}for(const r of model.racks)for(const a of model.areas)if(overlaps(r,a))result.push({id:r.id,text:`${r.name} 占用${a.name}`});return result;}
